import {initial,actions,apply,edge} from './engine.js';
const u=(t,c='w',parts=[t])=>({t,c,parts});
function board(pieces){const s=initial();s.board={'-3,6':u('k'),'3,-6':u('k','b'),...pieces};s.flux={w:6,b:6};return s;}
const pass={kind:'pass'};
export const LESSONS=[
{title:'Move & capture',category:'The familiar pieces',text:'A Rook follows six straight hex directions. Capture the black Pawn on G5.',state:()=>board({'0,0':u('r'),'0,-2':u('p','b')}),steps:[{mode:'move',want:{kind:'move',from:'0,0',to:'0,-2'},hint:'Select the Rook on G7, then the Pawn on G5.'}]},
{title:'Bishop diagonals',category:'The familiar pieces',text:'A Bishop follows vertex diagonals and stays on the same tile color. Move from G7 to I6.',state:()=>board({'0,0':u('b')}),steps:[{mode:'move',want:{kind:'move',from:'0,0',to:'2,-1'},hint:'Select G7, then I6. Notice that the Bishop skips the off-ray hexes.'}]},
{title:'Knight jumps',category:'The familiar pieces',text:'The Knight can jump over pieces. Land on I8, beyond the friendly Pawn.',state:()=>board({'0,0':u('n'),'1,0':u('p')}),steps:[{mode:'move',want:{kind:'move',from:'0,0',to:'2,1'},hint:'Select the Knight on G7, then I8.'}]},
{title:'Pawn capture',category:'The familiar pieces',text:'Pawns move forward but capture on two forward flanks. Capture the Pawn on H6.',state:()=>board({'0,0':u('p'),'1,-1':u('p','b')}),steps:[{mode:'move',want:{kind:'move',from:'0,0',to:'1,-1'},hint:'G7 → H6 is a capture flank, not the forward move.'}]},
{title:'Bee & swarm',category:'New pieces',text:'Fly over a piece, then coordinate a second Bee. Both actions belong to the same turn.',state:()=>board({'0,1':u('e'),'0,0':u('p'),'2,1':u('e')}),steps:[{mode:'move',want:{kind:'move',from:'0,1',to:'0,-1'},hint:'Fly the Bee on G8 to the empty G6.'},{mode:'move',want:{kind:'swarm',from:'2,1',to:'2,0'},hint:'Now step the other Bee from I8 to I7. Swarm cannot capture or chain.'}]},
{title:'Build & split a Hive',category:'New pieces',text:'Two Bees can become a Hive or Hornet. Choose Hive, then turn it back into two Bees.',state:()=>board({'0,1':u('e'),'1,1':u('e')}),steps:[{mode:'fuse',want:{kind:'fuse',from:'0,1',to:'1,1',result:'h'},reply:[pass],hint:'Fuse G8 into H8 and choose Hive. Black will pass automatically.'},{mode:'ability',want:{kind:'split',from:'1,1',to:'2,1',second:'1,2'},hint:'Select the Hive on H8, then I8. Choose the split into I8 and H9.'}]},
{title:'Call a reinforcement',category:'Board strategy',text:'Spend flux to deploy from reserve onto an empty home hex. No piece is created for free.',state:()=>board({}),steps:[{mode:'deploy',piece:'e',want:{kind:'deploy',piece:'e',to:'0,5'},hint:'Select the Bee reserve card, then G12. The cost is 2 flux.'}]},
{title:'A visible Guard',category:'Board strategy',text:'Mark a hex for a reaction. Black will enter it so you can watch your Rook intercept.',state:()=>board({'0,0':u('r'),'2,-1':u('r','b')}),steps:[{mode:'guard',want:{kind:'guard',from:'0,0',to:'2,0'},reply:[{kind:'move',from:'2,-1',to:'2,0'}],hint:'Select G7, then guard I7. The opponent demonstration follows automatically.'}]},
{title:'Use the Nexus',category:'Board strategy',text:'Occupying G7 unlocks an action, not free income. Harvest, then recall a Knight.',state:()=>{const s=board({'0,0':u('r'),'2,1':u('n')});s.flux.w=2;return s;},steps:[{mode:'nexus',want:{kind:'harvest'},reply:[pass],hint:'Press Harvest +3. Black will pass, without giving you passive income.'},{mode:'nexus',want:{kind:'recall',from:'2,1',to:'2,1'},hint:'Click the Knight on I8 to send it back to your reserve.'}]},
{title:'Courier transport',category:'New pieces',text:'The Courier carries a friendly unit but cannot capture. Loading and unloading each cost one turn.',state:()=>board({'0,0':u('u'),'1,0':u('q')}),steps:[{mode:'ability',want:{kind:'load',from:'0,0',to:'1,0'},reply:[pass],hint:'Select Courier G7, then Queen H7 to load. Black passes.'},{mode:'ability',want:{kind:'unload',from:'0,0',to:'0,1'},hint:'Select the Courier again, then empty G8 to unload.'}]},
{title:'Royal Exchange',category:'King safety',text:'Once per game, swap your King with a neighboring unfused Pawn. This is not invulnerability.',state:()=>{const s=board({'0,0':u('k'),'1,0':u('p')});delete s.board['-3,6'];return s;},steps:[{mode:'ability',want:{kind:'exchange',from:'0,0',to:'1,0'},hint:'Select King G7, then Pawn H7. Your exchange right is spent.'}]},
{title:'Break an Anchor',category:'New pieces',text:'An enemy Anchor disables nearby jumps. Capture the Anchor, then move the freed Knight.',state:()=>board({'0,0':u('n'),'1,0':u('t','b'),'1,2':u('r')}),steps:[{mode:'move',want:{kind:'move',from:'1,2',to:'1,0'},reply:[pass],hint:'The Knight on G7 cannot jump. Use the Rook from H9 to capture H7.'},{mode:'move',want:{kind:'move',from:'0,0',to:'2,1'},hint:'The Anchor is gone. Move Knight G7 to I8.'}]},
{title:'Borrow with a Mimic',category:'New pieces',text:'The Mimic next to a friendly Rook can borrow its sliding movement. It copies no special abilities.',state:()=>board({'0,0':u('m'),'1,0':u('r')}),steps:[{mode:'move',want:{kind:'move',from:'0,0',to:'0,-2'},hint:'Move Mimic G7 to G5, using the adjacent Rook’s movement.'}]},
{title:'Build a wall',category:'Board strategy',text:'A wall blocks both armies. It costs 1 flux and the whole turn. Knights can jump over it.',state:()=>board({'0,0':u('r'),'0,-4':u('r','b')}),steps:[{mode:'wall',want:{kind:'wall',key:edge('0,-1','0,-2')},hint:'Click the boundary between G6 and G5. The legal edge is highlighted.'}]},
{title:'Travel through a gate',category:'Board strategy',text:'A completed gate pair is shared. A piece must already be on an endpoint to travel.',state:()=>{const s=board({'0,1':u('r')});s.gates.w=['0,1','2,1'];return s;},steps:[{mode:'move',want:{kind:'move',from:'0,1',to:'2,1'},hint:'Move the Rook from G8 to I8 through the paired gate.'}]},
{title:'Capture the King',category:'King safety',text:'There is no checkmate. The game ends when a King is actually captured. Finish this position.',state:()=>{const s=board({'0,0':u('r'),'0,-2':u('k','b')});delete s.board['3,-6'];return s;},steps:[{mode:'move',want:{kind:'move',from:'0,0',to:'0,-2'},hint:'Capture the King on G5 with the Rook on G7.'}]}
];
export const matches=(a,want)=>Object.entries(want).every(([k,v])=>a[k]===v);
export function solveLesson(index){let s=LESSONS[index].state();for(const step of LESSONS[index].steps){const a=actions(s).find(a=>matches(a,step.want));if(!a)throw new Error(`Lesson ${index+1}: unavailable action`);s=apply(s,a);for(const want of step.reply||[]){const reply=actions(s).find(a=>matches(a,want));if(!reply)throw new Error(`Lesson ${index+1}: unavailable reply`);s=apply(s,reply);}}return s;}
